    pos = observation.get("position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)
    grid = observation.get("grid", [])
    if not isinstance(grid, list) or len(grid) == 0:
        grid = []

    # Basic local lookahead: prefer moving towards highest local "goal" signal if present
    # Scan neighboring cells for simple signals if grid provided as 2D list of dicts with "signal" keys
    best_dx, best_dy = 0, 0
    best_score = -float("inf")

    # Helper to evaluate a candidate move
    def eval_candidate(nx, ny):
        score = 0
        if isinstance(grid, list) and grid:
            if 0 <= ny < len(grid) and 0 <= nx < len(grid[ny]):
                cell = grid[ny][nx]
                if isinstance(cell, dict):
                    score += cell.get("signal", 0)
                    score += cell.get("value", 0)
        # Add slight bias to keep stable if no signals
        if nx == x and ny == y:
            score += 0.0
        return score

    # Check 8 surrounding positions within bounds and pick best
    for dx_try in (-1, 0, 1):
        for dy_try in (-1, 0, 1):
