            if s > best_score:
                best_score = s
                best_dx, best_dy = dx_try, dy_try

    # If there was a positive signal, move toward it; otherwise try to stay put
    if best_score > 0:
        dx, dy = best_dx, best_dy
    else:
        # Fallback: try to move toward any resource, if grid encodes resources as "resource" value in adjacent cells
        for dx_try in (-1, 0, 1):
